export function updateImportedBadge(el,age,count=1,head=false,family=null){const n=Math.max(1,Math.min(5,count)),root=family?`./assets/imported/feedback/${family}/${family==='xerofang'?'xero':'kuronami'}`:badgeRoot;for(const [layer,path]of Object.entries({bg:'bg/1',kill:`kill/${n}`,icon:`icons/${head?'headshot':'skull'}`,particles1:`particles1/${Math.min(6,1+Math.floor(age*12))}`,particles2:`particles2/${Math.min(13,1+Math.floor(age*18))}`})){const img=el.querySelector(`[data-layer="${layer}"]`),src=root+'/'+path+'.png';if(layer==='bg'&&img)img.style.display=family?'':'none';if(img&&(layer!=='bg'||family)&&img.getAttribute('src')!==weaponAssetURL(src))img.src=weaponAssetURL(src);}el.style.opacity=age>1.65?Math.max(0,(2.2-age)/.55):1;el.style.transform=`scale(${.82+.18*Math.min(1,age/.12)})`;}
